// Workflow inputs are untrusted. The scenario picks one of a fixed set of
// server-side settings; the prompt only ever becomes one argv element.
const SCENARIOS = {
  success: { env: [], activeDeadlineSeconds: 120 },
  // Deterministic failure: the agent needs 2 model requests when it calls a tool.
  limit: { env: [{ name: 'AGENT_LAB_MAX_REQUESTS', value: '1' }], activeDeadlineSeconds: 120 },
  // Controlled deadline: Kubernetes kills the Job after 1 second.
  timeout: { env: [], activeDeadlineSeconds: 1 },
};
const scenario = String($json.scenario ?? '');
if (!Object.hasOwn(SCENARIOS, scenario)) {
  throw new Error(`Rejected input: unknown scenario ${JSON.stringify(scenario.slice(0, 40))}`);
}
const prompt = String($json.prompt ?? '').trim();
if (prompt.length === 0 || prompt.length > 500) {
  throw new Error('Rejected input: prompt must be 1-500 characters');
}
if (/[\u0000-\u001f\u007f]/.test(prompt)) {
  throw new Error('Rejected input: prompt contains control characters');
}
return [{ json: { scenario, prompt, ...SCENARIOS[scenario] } }];

// Same pod shape as k8s/cronjob.yaml. admission-policy.yaml rejects anything else.
const { scenario, prompt, env, activeDeadlineSeconds } = $json;
const job = {
  apiVersion: 'batch/v1',
  kind: 'Job',
  metadata: {
    generateName: 'agent-lab-n8n-',
    labels: {
      'app.kubernetes.io/name': 'agent-lab',
      'app.kubernetes.io/managed-by': 'n8n',
      'agent-lab/scenario': scenario,
      'agent-lab/n8n-execution': String($execution.id).replace(/[^A-Za-z0-9]/g, '').slice(0, 63) || 'unknown',
    },
  },
  spec: {
    backoffLimit: 0, // agent failures are deterministic; the runtime owns retries
    activeDeadlineSeconds,
    ttlSecondsAfterFinished: 3600,
    template: {
      spec: {
        restartPolicy: 'Never',
        automountServiceAccountToken: false,
        securityContext: { runAsNonRoot: true, runAsUser: 10001, fsGroup: 10001, seccompProfile: { type: 'RuntimeDefault' } },
        containers: [{
          name: 'agent',
          image: 'agent-lab:dev',
          imagePullPolicy: 'IfNotPresent',
          args: ['run', '--', prompt], // `--` stops the CLI reading the prompt as flags
          env,
          envFrom: [{ configMapRef: { name: 'agent-lab-config' } }],
          resources: { requests: { cpu: '50m', memory: '128Mi' }, limits: { cpu: '500m', memory: '256Mi' } },
          securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: ['ALL'] } },
          volumeMounts: [{ name: 'runs', mountPath: '/data/runs' }, { name: 'tmp', mountPath: '/tmp' }],
        }],
        volumes: [
          { name: 'runs', persistentVolumeClaim: { claimName: 'agent-lab-runs' } },
          { name: 'tmp', emptyDir: {} },
        ],
      },
    },
  },
};
return [{ json: { job } }];

const input = $('Validate input').first().json;
return [{ json: {
  scenario: input.scenario,
  prompt: input.prompt,
  jobName: $json.metadata.name, // assigned by Kubernetes from generateName
  jobUid: $json.metadata.uid,
  submittedAt: new Date().toISOString(),
  startedMs: Date.now(),
  pollDeadlineSeconds: 90, // n8n's own deadline, independent of the Job's
  polls: 0,
} }];

const tracked = $('Track job').first().json;
const status = $json.status ?? {};
const done = (status.conditions ?? []).find(
  (c) => (c.type === 'Complete' || c.type === 'Failed') && c.status === 'True');
const elapsedSeconds = Math.round((Date.now() - tracked.startedMs) / 100) / 10;
let phase = 'running';
if (done) phase = done.type === 'Complete' ? 'succeeded' : 'failed';
else if (elapsedSeconds > tracked.pollDeadlineSeconds) phase = 'n8n_gave_up';
return [{ json: {
  ...tracked,
  polls: $runIndex + 1,
  phase,
  reason: done?.reason ?? null,
  message: done?.message ?? null,
  elapsedSeconds,
  active: status.active ?? 0,
  succeededPods: status.succeeded ?? 0,
  failedPods: status.failed ?? 0,
} }];

const pods = ($json.items ?? []).sort((a, b) =>
  a.metadata.creationTimestamp.localeCompare(b.metadata.creationTimestamp));
const pod = pods.at(-1);
const terminated = pod?.status?.containerStatuses?.[0]?.state?.terminated;
return [{ json: {
  podName: pod?.metadata?.name ?? 'none',
  podPhase: pod?.status?.phase ?? null,
  exitCode: terminated?.exitCode ?? null,
  terminationReason: terminated?.reason ?? null,
} }];

const job = $('Evaluate status').last().json;
const pod = $('Pick pod').first().json;
let record = null;
let logNote = null;
if ($json.error) logNote = `log unavailable: ${$json.error.message ?? JSON.stringify($json.error)}`;
else {
  try { record = JSON.parse($json.log); } catch { logNote = `log was not a run record: ${String($json.log ?? '').slice(0, 200)}`; }
}
let outcome;
if (job.phase === 'succeeded' && record?.status === 'succeeded') outcome = 'SUCCESS';
else if (job.reason === 'DeadlineExceeded') outcome = 'TIMEOUT (Kubernetes activeDeadlineSeconds)';
else if (job.phase === 'n8n_gave_up') outcome = 'TIMEOUT (n8n stopped waiting and deleted the Job)';
else if (record?.status === 'failed') outcome = `FAILED (agent error_class=${record.error_class})`;
else outcome = `FAILED (${job.reason ?? 'unknown'})`;
return [{ json: {
  outcome,
  scenario: job.scenario,
  prompt: job.prompt,
  job: { name: job.jobName, uid: job.jobUid, phase: job.phase, reason: job.reason, message: job.message,
         submittedAt: job.submittedAt, elapsedSeconds: job.elapsedSeconds, polls: job.polls },
  pod,
  agent: record && {
    run_id: record.run_id, status: record.status, error_class: record.error_class ?? null,
    error: record.error ?? null, output: record.output ?? null, tools_used: record.tools_used,
    requests: record.requests, model: record.model, git_sha: record.git_sha, config_hash: record.config_hash,
  },
  logNote,
} }];
